<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>Cartes de bibliothèque</title><style>
*{box-sizing:border-box}body{margin:0;background:#e2e8f0;font-family:Arial,sans-serif;color:#0f172a}.toolbar{display:flex;align-items:center;gap:12px;padding:14px 20px;background:#fff}.toolbar button{border:0;border-radius:6px;background:#4f46e5;color:#fff;padding:10px 16px;font-weight:700}.sheet{display:grid;grid-template-columns:repeat(2,85.6mm);grid-auto-rows:53.98mm;gap:3mm;width:190mm;min-height:277mm;margin:16px auto;padding:0;background:#fff}.card{position:relative;width:85.6mm;height:53.98mm;overflow:hidden;border:.25mm dotted #94a3b8;border-radius:3mm;background:#fff}.top{position:absolute;inset:0 0 auto;height:11mm;padding:2.4mm 4mm;background:#111a33;color:#fff}.school{font-size:10pt;font-weight:800}.subtitle{margin-top:.5mm;font-size:5.8pt;letter-spacing:.1em;text-transform:uppercase;color:#c7d2fe}.photo{position:absolute;top:14mm;left:3mm;width:17mm;height:24mm;border:.25mm solid #cbd5e1;border-radius:1.5mm;object-fit:cover}.photo-placeholder{position:absolute;top:14mm;left:3mm;width:17mm;height:24mm;border:.25mm dashed #94a3b8;background:#f1f5f9;text-align:center;padding-top:9mm;font-size:6pt;color:#64748b}.identity{position:absolute;top:13.5mm;left:22.5mm;width:39mm;height:30mm;overflow:hidden}.name{max-height:10.5mm;overflow:hidden;font-weight:800;line-height:1.08;text-transform:uppercase;overflow-wrap:anywhere}.name-normal{font-size:9pt}.name-compact{font-size:7.4pt}.name-very-compact{font-size:6.2pt}.meta{margin-top:.9mm;font-size:5.9pt;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#475569}.qr{position:absolute;top:14mm;right:3mm;width:19.5mm;height:19.5mm}.qr svg{width:19.5mm!important;height:19.5mm!important}.card-number{position:absolute;top:34.5mm;right:2.5mm;width:20.5mm;text-align:center;font:700 5.5pt monospace}.footer{position:absolute;right:3mm;bottom:2.5mm;left:3mm;display:flex;justify-content:space-between;border-top:.2mm solid #e2e8f0;padding-top:1.4mm;font-size:5.5pt;color:#64748b}@page{size:A4 portrait;margin:10mm}@media print{body{background:#fff}.toolbar{display:none}.sheet{margin:0;break-after:page}.sheet:last-child{break-after:auto}}
</style></head><body><div class="toolbar"><button onclick="window.print()">Imprimer {{ $cards->count() }} cartes</button><span>Planche A4 · format CR80</span></div>@foreach($cards->chunk(10) as $page)<main class="sheet">@foreach($page as $card)@php $fullName=trim($card->student->last_name.' '.$card->student->first_name);$nameClass=mb_strlen($fullName)>48?'name-very-compact':(mb_strlen($fullName)>30?'name-compact':'name-normal');@endphp<article class="card"><header class="top"><div class="school">BIBLIOTHÈQUE EDSP</div><div class="subtitle">Université de Mahajanga · Carte de bibliothèque</div></header>@if($card->student->photo_url)<img class="photo" src="{{ $card->student->photo_url }}">@else<div class="photo-placeholder">PHOTO</div>@endif<section class="identity"><div class="name {{ $nameClass }}">{{ $fullName }}</div><div class="meta"><b>N° interne :</b> {{ $card->student->registration_number }}</div><div class="meta"><b>Matricule :</b> {{ $card->student->academic_number ?: '—' }}</div><div class="meta"><b>Niveau :</b> {{ $card->student->academicLevel?->name ?: ($card->student->level ?: '—') }}</div><div class="meta"><b>Parcours :</b> {{ $card->student->academicProgram?->name ?: ($card->student->program ?: '—') }}</div></section><div class="qr">{!! $codes[$card->id] !!}</div><div class="card-number">{{ $card->card_number }}</div><footer class="footer"><span>Délivrée : <b>{{ $card->issued_at?->format('d/m/Y') }}</b></span><span>Expire : <b>{{ $card->expires_at?->format('d/m/Y') ?: 'sans limite' }}</b></span></footer></article>@endforeach</main>@endforeach</body></html>
